import pytest
from src.errors import AppError, NetworkError, TimeoutError, AuthError


def test_network_error_is_app_error():
    assert issubclass(NetworkError, AppError)


def test_timeout_error_is_app_error():
    assert issubclass(TimeoutError, AppError)


def test_auth_error_is_app_error():
    assert issubclass(AuthError, AppError)


def test_catch_as_app_error():
    with pytest.raises(AppError):
        raise NetworkError("connection refused")


def test_individual_catch_still_works():
    with pytest.raises(NetworkError):
        raise NetworkError("connection refused")

